-- Clean up existing seeded records
DELETE FROM profile_photos WHERE user_id LIKE 'seeded_user_%';
DELETE FROM trust_metrics WHERE user_id LIKE 'seeded_user_%';
DELETE FROM user_interests WHERE user_id LIKE 'seeded_user_%';
DELETE FROM user_intents WHERE user_id LIKE 'seeded_user_%';
DELETE FROM user_preferences WHERE user_id LIKE 'seeded_user_%';
DELETE FROM profiles WHERE user_id LIKE 'seeded_user_%';
DELETE FROM users WHERE id LIKE 'seeded_user_%';
DELETE FROM events WHERE id LIKE 'seeded_event_%';
DELETE FROM event_attendees WHERE event_id LIKE 'seeded_event_%';
DELETE FROM event_feedback WHERE event_id LIKE 'seeded_event_%';
DELETE FROM match_outcomes WHERE id LIKE 'seeded_outcome_%';
DELETE FROM meetup_feedback WHERE id LIKE 'seeded_feedback_%';
DELETE FROM chats WHERE slug LIKE 'seeded-chat-%';
DELETE FROM chat_messages WHERE chat_id LIKE 'chat-seeded-%';
DELETE FROM instant_plans WHERE id LIKE 'seeded_plan_%';
DELETE FROM instant_plan_members WHERE plan_id LIKE 'seeded_plan_%';
DELETE FROM analytics_events WHERE seed_data = 1;

